import * as THREE from './vendor/three.module.js';
export const TILE=4,SIZE=48,HALF=96;
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n)),smooth=t=>t*t*(3-2*t);
function hash(x,y,seed){let v=Math.imul(x,374761393)+Math.imul(y,668265263)+seed*31;v=Math.imul(v^(v>>>13),1274126177);return((v^(v>>>16))>>>0)/4294967295}
function noise(x,y,seed){const a=Math.floor(x),b=Math.floor(y),u=smooth(x-a),v=smooth(y-b);return THREE.MathUtils.lerp(THREE.MathUtils.lerp(hash(a,b,seed),hash(a+1,b,seed),u),THREE.MathUtils.lerp(hash(a,b+1,seed),hash(a+1,b+1,seed),u),v)}
function wetTile(w,x,y){if(x>=0&&y>=0&&x<SIZE&&y<SIZE)return w.tiles[y*SIZE+x].ground==='water'?1:0;if(w.terrain==='river')return Math.abs(x-(34+Math.sin(y/7+w.seed%9)*3))<2.3?1:0;if(w.terrain==='islands')return Math.sin(x/7)+Math.cos(y/8)+Math.sin((x+y)/9)>1.05?1:0;return 0}
export function wetness(w,x,z){const gx=(x+HALF)/TILE-.5,gy=(z+HALF)/TILE-.5,a=Math.floor(gx),b=Math.floor(gy),u=gx-a,v=gy-b;return THREE.MathUtils.lerp(THREE.MathUtils.lerp(wetTile(w,a,b),wetTile(w,a+1,b),u),THREE.MathUtils.lerp(wetTile(w,a,b+1),wetTile(w,a+1,b+1),u),v)}
export function groundHeight(w,x,z){const water=wetness(w,x,z),inland=.35+noise(x*.014,z*.014,w.seed)*2.4+noise(x*.035,z*.035,w.seed+3)*.9;const edge=clamp((Math.hypot(x,z)-130)/170,0,1);const hills=edge*(noise(x*.008,z*.008,w.seed+8)*40+noise(x*.02,z*.02,w.seed+11)*14);return inland*(1-smooth(clamp(water*1.35,0,1)))+hills*(1-water)-water*2.4;}
export function floorHeight(w,x,z){return Math.max(.2,groundHeight(w,x,z))}
export class Landscape{
constructor(view){this.view=view;this.group=new THREE.Group();view.scene.add(this.group);this.loader=new THREE.TextureLoader();this.assets={};this.ready=this.load();}
async load(){const defs=['grass-color','grass-normal','grass-rough','asphalt-color','asphalt-normal','asphalt-rough','brick-color','brick-normal','brick-rough'];await Promise.all(defs.map(async name=>{try{const t=await this.loader.loadAsync(new URL('./assets/'+name+'.jpg',import.meta.url).href);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.anisotropy=this.view.renderer.capabilities.getMaxAnisotropy();if(name.endsWith('color'))t.colorSpace=THREE.SRGBColorSpace;this.assets[name]=t}catch(e){console.warn('Texture fallback:',name)}}));}
material(name,repeat=1,color='#ffffff'){const map=this.assets[name+'-color']?.clone(),normal=this.assets[name+'-normal']?.clone(),rough=this.assets[name+'-rough']?.clone();for(let t of [map,normal,rough])if(t){t.repeat.set(repeat,repeat);t.needsUpdate=true}return new THREE.MeshStandardMaterial({color,map,normalMap:normal,roughnessMap:rough,normalScale:new THREE.Vector2(.3,.3),roughness:.92});}
clear(){this.group.traverse(o=>{if(o.geometry)o.geometry.dispose();if(o.material){for(let m of Array.isArray(o.material)?o.material:[o.material]){if([...this.view.materials.values()].includes(m))continue;for(let k of ['map','normalMap','roughnessMap'])if(m[k]&&!Object.values(this.assets).includes(m[k]))m[k].dispose();m.dispose()}}});this.group.clear()}
build(w){this.clear();this.world=w;const geo=new THREE.PlaneGeometry(192,192,192,192);geo.rotateX(-Math.PI/2);const pos=geo.attributes.position,colors=[];for(let i=0;i<pos.count;i++){const x=pos.getX(i),z=pos.getZ(i),h=groundHeight(w,x,z),wet=wetness(w,x,z);pos.setY(i,h);const shade=.86+noise(x*.08,z*.08,w.seed)*.19;const col=new THREE.Color(wet>.08&&wet<.65?'#c0b49b':'#b7c39c');col.multiplyScalar(shade);colors.push(col.r,col.g,col.b)}geo.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));geo.computeVertexNormals();const mat=this.material('grass',14,'#d0c5a6');mat.vertexColors=true;mat.normalScale.set(.55,.55);this.ground=new THREE.Mesh(geo,mat);this.ground.receiveShadow=true;this.group.add(this.ground);
const far=new THREE.PlaneGeometry(1100,1100,130,130);far.rotateX(-Math.PI/2);const fp=far.attributes.position;for(let i=0;i<fp.count;i++)fp.setY(i,groundHeight(w,fp.getX(i),fp.getZ(i))-.1);let ind=[];const arr=far.index.array;for(let i=0;i<arr.length;i+=3){let x=0,z=0;for(let j=0;j<3;j++){x+=fp.getX(arr[i+j])/3;z+=fp.getZ(arr[i+j])/3}if(Math.abs(x)>95||Math.abs(z)>95)ind.push(arr[i],arr[i+1],arr[i+2])}far.setIndex(ind);far.computeVertexNormals();const fm=this.material('grass',70,'#aca88b');this.surroundings=new THREE.Mesh(far,fm);this.surroundings.receiveShadow=true;this.group.add(this.surroundings);
this.waterMaterial=new THREE.ShaderMaterial({uniforms:{time:{value:0},sun:{value:new THREE.Vector3(-.4,.75,.35)},night:{value:0}},vertexShader:`varying vec3 worldPos;varying vec3 viewDir;void main(){vec4 p=modelMatrix*vec4(position,1.);worldPos=p.xyz;viewDir=cameraPosition-p.xyz;gl_Position=projectionMatrix*viewMatrix*p;}`,fragmentShader:`precision highp float;uniform float time;uniform float night;uniform vec3 sun;varying vec3 worldPos;varying vec3 viewDir;void main(){vec2 p=worldPos.xz;float a=sin(p.x*1.8+p.y*.9+time*.7),b=cos(p.x*.7-p.y*2.2-time*.85);vec3 n=normalize(vec3(a*.065,1.,b*.08));vec3 v=normalize(viewDir);float fres=pow(1.-max(dot(v,n),0.),3.);float glint=pow(max(dot(reflect(-normalize(sun),n),v),0.),110.);float ripple=.5+.5*sin(p.x*.5+p.y*.8+time*.3);vec3 deep=mix(vec3(.10,.22,.24),vec3(.20,.32,.34),ripple*.3);vec3 c=mix(deep,vec3(.56,.67,.69),fres*.65)+glint*.6;c=mix(c,c*.32,night);gl_FragColor=vec4(c,1.);}`,side:THREE.DoubleSide});this.water=new THREE.Mesh(new THREE.PlaneGeometry(1100,1100),this.waterMaterial);this.water.rotation.x=-Math.PI/2;this.water.position.y=-.1;this.group.add(this.water);this.makeTrees(w);}
makeTrees(w){const positions=[];w.tiles.forEach((t,i)=>{if(t.tree&&!t.type&&t.ground==='land'){const x=(i%48+.5)*4-96,z=(Math.floor(i/48)+.5)*4-96;for(let j=0;j<2+(t.variant%2);j++){let px=x+hash(i,j,w.seed)*3-1.5,pz=z+hash(j,i,w.seed)*3-1.5;if(wetness(w,px,pz)<.22)positions.push([px,pz,2.4+hash(i,j+3,w.seed)*2.6,i%3])}}});
const trunk=new THREE.InstancedMesh(new THREE.CylinderGeometry(.1,.21,1,7),this.view.mat('#655a43'),positions.length);const leaves=new THREE.InstancedMesh(new THREE.IcosahedronGeometry(1,2),this.view.mat('#4c6140'),positions.length*4);let d=new THREE.Object3D();positions.forEach(([x,z,h,v],i)=>{let y=floorHeight(w,x,z);d.position.set(x,y+h*.42,z);d.scale.set(1,h*.85,1);d.updateMatrix();trunk.setMatrixAt(i,d.matrix);for(let j=0;j<4;j++){let a=j*2.4+i;d.position.set(x+Math.cos(a)*.48,y+h*.55+j*h*.12,z+Math.sin(a)*.48);d.scale.set(h*.25*(j===3?.65:1),h*.28,h*.25);d.rotation.set(.1*i,a,.2*j);d.updateMatrix();leaves.setMatrixAt(i*4+j,d.matrix);let col=new THREE.Color(['#536644','#465d3f','#6d7547'][v]);col.multiplyScalar(.8+hash(i,j,w.seed)*.35);leaves.setColorAt(i*4+j,col)}});trunk.castShadow=true;leaves.castShadow=true;leaves.receiveShadow=true;this.group.add(trunk,leaves);this.trees=[trunk,leaves];}
refreshTrees(w){for(let o of this.trees||[]){this.group.remove(o);o.dispose();o.geometry.dispose()}this.makeTrees(w)}
update(time,night){if(this.waterMaterial){this.waterMaterial.uniforms.time.value=time;this.waterMaterial.uniforms.night.value=night?1:0}}
}
